/**
 * 🔐 KEY BACKUP STORE
 * Sistema de backup persistente de chaves usando SQLite
 * Armazena backups de sessões e sender keys para recuperação em caso de acidente
 */

import * as fs from 'fs'
import * as path from 'path'

// Tipo para o banco de dados better-sqlite3
type Database = {
	prepare: (sql: string) => any
	exec: (sql: string) => void
	close: () => void
}

export class KeyBackupStore {
	private db: Database | null = null
	private initialized = false
	private dbPath: string

	constructor(sessionFolder?: string) {
		// Encontrar a pasta de dados baseado na pasta da sessão ou usar padrão
		if (sessionFolder) {
			this.dbPath = path.join(sessionFolder, 'chaves.db')
		} else {
			// Usar variável de ambiente DB_PATH ou padrão dados/DB
			const dbFolder = process.env.DB_PATH || path.join('dados', 'DB')

			// Tentar encontrar a pasta dados/DB a partir do diretório raiz
			const possiblePaths: string[] = [
				path.join(process.cwd(), dbFolder, 'chaves.db'),
				path.join(process.cwd(), '..', dbFolder, 'chaves.db'),
				path.join(__dirname, '..', '..', '..', '..', dbFolder, 'chaves.db'),
			]

			// Usar o primeiro caminho onde a pasta pai existe
			this.dbPath = possiblePaths[0]!
			for (const p of possiblePaths) {
				const dir = path.dirname(p)
				if (fs.existsSync(dir)) {
					this.dbPath = p
					break
				}
			}
		}
	}

	/**
	 * Inicializa o banco de dados de backup
	 */
	async init(): Promise<boolean> {
		if (this.initialized) return true

		try {
			// Garantir que o diretório existe
			const dir = path.dirname(this.dbPath)
			if (!fs.existsSync(dir)) {
				fs.mkdirSync(dir, { recursive: true })
			}

			// Importar better-sqlite3 dinamicamente (compatível com ESM)
			// @ts-ignore - better-sqlite3 não tem tipos
			const { default: Database } = await import('better-sqlite3')
			this.db = new Database(this.dbPath)

			// Criar tabelas se não existirem
			this.db!.exec(`
				CREATE TABLE IF NOT EXISTS session_backup (
					id TEXT PRIMARY KEY,
					data TEXT NOT NULL,
					created_at INTEGER DEFAULT (strftime('%s', 'now')),
					updated_at INTEGER DEFAULT (strftime('%s', 'now'))
				);

				CREATE TABLE IF NOT EXISTS sender_key_backup (
					id TEXT PRIMARY KEY,
					data TEXT NOT NULL,
					created_at INTEGER DEFAULT (strftime('%s', 'now')),
					updated_at INTEGER DEFAULT (strftime('%s', 'now'))
				);

				CREATE INDEX IF NOT EXISTS idx_session_updated ON session_backup(updated_at);
				CREATE INDEX IF NOT EXISTS idx_sender_key_updated ON sender_key_backup(updated_at);
			`)

			// Limpar backups antigos (mais de 7 dias)
			const sevenDaysAgo = Math.floor(Date.now() / 1000) - (7 * 24 * 60 * 60)
			this.db!.prepare('DELETE FROM session_backup WHERE updated_at < ?').run(sevenDaysAgo)
			this.db!.prepare('DELETE FROM sender_key_backup WHERE updated_at < ?').run(sevenDaysAgo)

			this.initialized = true
			// console.log(`🔐 [KEY-BACKUP] Banco de backup inicializado: ${this.dbPath}`)
			return true
		} catch (error) {
			console.warn(`⚠️ [KEY-BACKUP] Falha ao inicializar banco de backup:`, (error as Error).message)
			return false
		}
	}

	/**
	 * Salva backup de uma sessão
	 */
	async backupSession(sessionId: string, data: any): Promise<boolean> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return false

		try {
			const jsonData = JSON.stringify(data)
			const now = Math.floor(Date.now() / 1000)
			
			this.db.prepare(`
				INSERT INTO session_backup (id, data, updated_at) 
				VALUES (?, ?, ?)
				ON CONFLICT(id) DO UPDATE SET data = ?, updated_at = ?
			`).run(sessionId, jsonData, now, jsonData, now)
			
			return true
		} catch (error) {
			return false
		}
	}

	/**
	 * Recupera backup de uma sessão
	 */
	async getSessionBackup(sessionId: string): Promise<any | null> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return null

		try {
			const row = this.db.prepare('SELECT data FROM session_backup WHERE id = ?').get(sessionId) as { data: string } | undefined
			if (row?.data) {
				return JSON.parse(row.data)
			}
		} catch (error) {
			// Silently ignore
		}
		return null
	}

	/**
	 * Remove backup de uma sessão
	 */
	async deleteSessionBackup(sessionId: string): Promise<void> {
		if (!this.db) return
		try {
			this.db.prepare('DELETE FROM session_backup WHERE id = ?').run(sessionId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * Salva backup de uma sender key
	 */
	async backupSenderKey(keyId: string, data: any): Promise<boolean> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return false

		try {
			const jsonData = JSON.stringify(data)
			const now = Math.floor(Date.now() / 1000)
			
			this.db.prepare(`
				INSERT INTO sender_key_backup (id, data, updated_at) 
				VALUES (?, ?, ?)
				ON CONFLICT(id) DO UPDATE SET data = ?, updated_at = ?
			`).run(keyId, jsonData, now, jsonData, now)
			
			return true
		} catch (error) {
			return false
		}
	}

	/**
	 * Recupera backup de uma sender key
	 */
	async getSenderKeyBackup(keyId: string): Promise<any | null> {
		if (!this.initialized || !this.db) {
			await this.init()
		}
		if (!this.db) return null

		try {
			const row = this.db.prepare('SELECT data FROM sender_key_backup WHERE id = ?').get(keyId) as { data: string } | undefined
			if (row?.data) {
				return JSON.parse(row.data)
			}
		} catch (error) {
			// Silently ignore
		}
		return null
	}

	/**
	 * Remove backup de uma sender key
	 */
	async deleteSenderKeyBackup(keyId: string): Promise<void> {
		if (!this.db) return
		try {
			this.db.prepare('DELETE FROM sender_key_backup WHERE id = ?').run(keyId)
		} catch (error) {
			// Silently ignore
		}
	}

	/**
	 * Retorna estatísticas do backup
	 */
	getStats(): { sessions: number; senderKeys: number; dbPath: string } {
		if (!this.db) {
			return { sessions: 0, senderKeys: 0, dbPath: this.dbPath }
		}

		try {
			const sessions = (this.db.prepare('SELECT COUNT(*) as count FROM session_backup').get() as { count: number })?.count || 0
			const senderKeys = (this.db.prepare('SELECT COUNT(*) as count FROM sender_key_backup').get() as { count: number })?.count || 0
			return { sessions, senderKeys, dbPath: this.dbPath }
		} catch (error) {
			return { sessions: 0, senderKeys: 0, dbPath: this.dbPath }
		}
	}

	/**
	 * Fecha a conexão com o banco
	 */
	close(): void {
		if (this.db) {
			try {
				this.db.close()
			} catch (error) {
				// Silently ignore
			}
			this.db = null
			this.initialized = false
		}
	}
}

// Instância global do backup store (será inicializada quando necessário)
let globalBackupStore: KeyBackupStore | null = null

export function getKeyBackupStore(sessionFolder?: string): KeyBackupStore {
	if (!globalBackupStore) {
		globalBackupStore = new KeyBackupStore(sessionFolder)
	}
	return globalBackupStore
}
